-- SEC-092 remediation (1): an admin can hide a review (DATA_MODEL.md sections 6.15 and 21.8).
-- Additive only: four nullable or defaulted columns, one foreign key, two check constraints, one
-- partial index. No existing row changes meaning; every existing review stays public.
-- There is no down migration; the manual undo is in DATA_MODEL.md section 17.

-- AlterTable (generated by Prisma)
ALTER TABLE "Review" ADD COLUMN     "hiddenAt" TIMESTAMPTZ(3),
ADD COLUMN     "hiddenByUserId" TEXT,
ADD COLUMN     "hiddenReason" TEXT,
ADD COLUMN     "updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- AddForeignKey (generated by Prisma)
ALTER TABLE "Review" ADD CONSTRAINT "Review_hiddenByUserId_fkey" FOREIGN KEY ("hiddenByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Hand-written below: Prisma cannot express these (DATA_MODEL.md section 13).

-- Backfill: a review was never changed before this migration, so its last change is its creation.
UPDATE "Review" SET "updatedAt" = "createdAt";

-- All three hide columns null (public), or hidden with its time and its admin; the reason is
-- optional when hidden and must be null when not hidden.
ALTER TABLE "Review" ADD CONSTRAINT "Review_hidden_pair_check" CHECK (
  ("hiddenAt" IS NULL AND "hiddenByUserId" IS NULL AND "hiddenReason" IS NULL)
  OR ("hiddenAt" IS NOT NULL AND "hiddenByUserId" IS NOT NULL)
);

-- The admin reason rule of API_CONTRACTS.md (1 to 500 characters); the service normalises first.
ALTER TABLE "Review" ADD CONSTRAINT "Review_hiddenReason_check" CHECK (
  "hiddenReason" IS NULL OR char_length("hiddenReason") BETWEEN 1 AND 500
);

-- The public list of a product's reviews and its rating summary read only rows that are not
-- hidden: WHERE "productId" = $1 AND "hiddenAt" IS NULL ORDER BY "createdAt" DESC, id DESC.
-- Same columns as "Review_productId_createdAt_idx", restricted to public rows. Plain CREATE INDEX
-- (not CONCURRENTLY): Prisma runs this file as one script; it blocks writes to "Review" while built.
CREATE INDEX "Review_productId_createdAt_visible_idx" ON "Review" ("productId", "createdAt") WHERE "hiddenAt" IS NULL;
